const XRANGEPLAINLOOSE = '[v=\\s]*(' + XIDLOOSE + ')(?:\\.(' + XIDLOOSE + ')(?:\\.(' + XIDLOOSE + ')(?:' + PRELOOSE + ')?' + BUILD + '?)?)?'

