const BUILDSTRIP_RE = /(?:\+([a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*))/g

// parsed ranges, oldest first, at most 1000
const rangeCache = new Map()

// hoisted class for cyclic dependency
class Range {
  constructor (range, options) {
    if (!options) {
