      if (!fM || fM.toLowerCase() === 'x' || fM === '*') {
        from = ''
      } else if (!fm || fm.toLowerCase() === 'x' || fm === '*') {
        from = `>=${fM}.0.0${incPr ? '-0' : ''}`
      } else if (!fp || fp.toLowerCase() === 'x' || fp === '*') {
        from = `>=${fM}.${fm}.0${incPr ? '-0' : ''}`
      } else if (fpr) {
        from = `>=${from}`
      } else {
