        to = ''
      } else if (!tm || tm.toLowerCase() === 'x' || tm === '*') {
        to = `<${+tM + 1}.0.0-0`
      } else if (!tp || tp.toLowerCase() === 'x' || tp === '*') {
        to = `<${tM}.${+tm + 1}.0-0`
      } else if (tpr) {
        to = `<=${tM}.${tm}.${tp}-${tpr}`
      } else if (incPr) {
        to = `<${tM}.${tm}.${+tp + 1}-0`
      } else {
        to = `<=${to}`
      }

